{
  "name": "kanban-board",
  "version": "1.0.0",
  "private": true,
  "scripts": {
    "dev": "concurrently \"npm run server\" \"npm run client\"",
    "server": "node server/index.js",
    "client": "vite --config vite.config.js"
  },
  "dependencies": {
    "@electric-sql/pglite": "^0.2.0",
    "cors": "^2.8.5",
    "express": "^4.18.2"
  },
  "devDependencies": {
    "concurrently": "^8.2.2",
    "vite": "^5.0.0"
  }
}

import { defineConfig } from 'vite';

export default defineConfig({
  root: 'client',
  server: {
    port: 3000,
    proxy: {
      '/api': 'http://localhost:3001',
    },
  },
  build: {
    outDir: '../dist',
  },
});

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  background: #0079bf;
  min-height: 100vh;
  padding: 20px;
}

#app {
  max-width: 100%;
}

h1 {
  color: white;
  margin-bottom: 20px;
  font-size: 1.5rem;
}

#board {
  display: flex;
  gap: 16px;
  overflow-x: auto;
  align-items: flex-start;
  padding-bottom: 20px;
}

.column {
  background: #ebecf0;
  border-radius: 8px;
  min-width: 280px;
  max-width: 280px;
  padding: 10px;
  flex-shrink: 0;
}

.column-header {
  font-weight: 600;
  padding: 8px 4px;
  font-size: 0.95rem;
  color: #172b4d;
}

.column-cards {
  min-height: 40px;
  padding: 4px 0;
}

.card {
  background: white;
  border-radius: 6px;
  padding: 8px 10px;
  margin-bottom: 8px;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.15);
  cursor: grab;
  font-size: 0.9rem;
  color: #172b4d;
  transition: background 0.15s, box-shadow 0.15s;
  word-wrap: break-word;
}

.card:hover {
  background: #f4f5f7;
}

.card.dragging {
  opacity: 0.5;
  cursor: grabbing;
}

.card.drop-target {
  box-shadow: 0 0 0 2px #0079bf;
}

.add-card-form {
  margin-top: 8px;
  display: flex;
  gap: 4px;
}

.add-card-form input {
  flex: 1;
  padding: 6px 8px;
  border: 2px solid #ddd;
  border-radius: 4px;
  font-size: 0.9rem;
  outline: none;
}

.add-card-form input:focus {
  border-color: #0079bf;
}

.add-card-form button {
  padding: 6px 10px;
  background: #0079bf;
  color: white;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  font-size: 0.85rem;
}

.add-card-form button:hover {
  background: #026aa7;
}

.column.drag-over {
  background: #d4e8f7;
}

const API_BASE = '/api';

// State management
let boardState = { columns: {} }; // { columnId: { title, cards: { cardId: { id, text, position } } } }
let dragState = null; // { cardId, fromColumnId, fromPosition }

// DOM cache
const domCache = new Map(); // cardId -> DOM element

// ==================== API Functions ====================

async function fetchBoard() {
  const res = await fetch(`${API_BASE}/board`);
  const data = await res.json();
  return data;
}

async function createCard(columnId, text) {
  const res = await fetch(`${API_BASE}/cards`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ columnId, text }),
  });
  return res.json();
}

async function moveCard(cardId, { columnId, beforeId, afterId }) {
  const res = await fetch(`${API_BASE}/cards/${cardId}/move`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ columnId, beforeId, afterId }),
  });
  return res.json();
}

// ==================== SSE Connection ====================

function connectSSE() {
  const eventSource = new EventSource(`${API_BASE}/stream`);

  eventSource.onmessage = (event) => {
    const data = JSON.parse(event.data);
    handleServerEvent(data);
  };

  eventSource.onerror = () => {
    console.error('SSE connection error, reconnecting...');
  };

  return eventSource;
}

function handleServerEvent(data) {
  if (data.type === 'card_created') {
    const { card, columnId } = data;
    addCardToState(card, columnId);
    renderCard(card, columnId);
  } else if (data.type === 'card_moved') {
    const { card, columnId } = data;
    removeCardFromState(card.id);
    addCardToState(card, columnId);
    // Re-render the entire board to ensure consistency
    renderBoard();
  } else if (data.type === 'renormalized') {
    // Full board state was renormalized
    boardState = { columns: {} };
    data.columns.forEach(col => {
      boardState.columns[col.id] = {
        title: col.title,
        cards: {},
      };
      col.cards.forEach(card => {
        boardState.columns[col.id].cards[card.id] = card;
      });
    });
    renderBoard();
  }
}

// ==================== State Management ====================

function addCardToState(card, columnId) {
  if (!boardState.columns[columnId]) {
    boardState.columns[columnId] = { title: '', cards: {} };
  }
  boardState.columns[columnId].cards[card.id] = card;
}

function removeCardFromState(cardId) {
  for (const colId in boardState.columns) {
    if (boardState.columns[colId].cards[cardId]) {
      delete boardState.columns[colId].cards[cardId];
      break;
    }
  }
}

// ==================== Rendering ====================

function renderBoard() {
  const boardEl = document.getElementById('board');
  boardEl.innerHTML = '';

  // Sort columns by position
  const columns = Object.values(boardState.columns).sort((a, b) => a.position - b.position);

  columns.forEach(col => {
    const columnEl = document.createElement('div');
    columnEl.className = 'column';
    columnEl.dataset.columnId = col.id;

    // Header
    const headerEl = document.createElement('div');
    headerEl.className = 'column-header';
    headerEl.textContent = col.title;
    columnEl.appendChild(headerEl);

    // Cards container
    const cardsEl = document.createElement('div');
    cardsEl.className = 'column-cards';
    cardsEl.dataset.columnId = col.id;

    // Sort cards by position
    const cards = Object.values(col.cards).sort((a, b) => a.position - b.position);

    cards.forEach(card => {
      renderCard(card, col.id);
      cardsEl.appendChild(domCache.get(card.id));
    });

    columnEl.appendChild(cardsEl);

    // Add card form
    const formEl = document.createElement('form');
    formEl.className = 'add-card-form';
    formEl.innerHTML = `
      <input type="text" placeholder="Add a card..." />
      <button type="submit">Add</button>
    `;
    formEl.addEventListener('submit', (e) => {
      e.preventDefault();
      const input = formEl.querySelector('input');
      const text = input.value.trim();
      if (text) {
        createCard(col.id, text).then(card => {
          input.value = '';
        });
      }
    });
    columnEl.appendChild(formEl);

    // Drop target handlers
    cardsEl.addEventListener('dragover', handleDragOver);
    cardsEl.addEventListener('drop', handleDrop);

    boardEl.appendChild(columnEl);
  });
}

function renderCard(card, columnId) {
  // Remove existing element if present
  if (domCache.has(card.id)) {
    domCache.get(card.id).remove();
  }

  const cardEl = document.createElement('div');
  cardEl.className = 'card';
  cardEl.draggable = true;
  cardEl.dataset.cardId = card.id;
  cardEl.textContent = card.text;

  cardEl.addEventListener('dragstart', handleDragStart);
  cardEl.addEventListener('dragend', handleDragEnd);

  domCache.set(card.id, cardEl);
}

// ==================== Drag and Drop ====================

function handleDragStart(e) {
  const cardId = e.target.dataset.cardId;
  // Find which column this card is in
  let fromColumnId = null;
  for (const colId in boardState.columns) {
    if (boardState.columns[colId].cards[cardId]) {
      fromColumnId = colId;
      break;
    }
  }

  dragState = {
    cardId,
    fromColumnId,
    fromPosition: boardState.columns[fromColumnId]?.cards[cardId]?.position,
  };

  e.target.classList.add('dragging');
  e.dataTransfer.effectAllowed = 'move';
  // Set a slight delay for the drag image
  setTimeout(() => {
    e.target.style.opacity = '0.5';
  }, 0);
}

function handleDragEnd(e) {
  e.target.classList.remove('dragging');
  e.target.style.opacity = '';
  document.querySelectorAll('.drop-target').forEach(el => el.classList.remove('drop-target'));
  document.querySelectorAll('.column.drag-over').forEach(el => el.classList.remove('drag-over'));
  dragState = null;
}

function handleDragOver(e) {
  e.preventDefault();
  e.dataTransfer.dropEffect = 'move';

  const columnEl = e.currentTarget;
  columnEl.classList.add('drag-over');

  // Find the card element we're over
  const cardEl = [...columnEl.querySelectorAll('.card:not(.dragging)')].find(
    el => {
      const rect = el.getBoundingClientRect();
      return e.clientY < rect.top + rect.height / 2;
    }
  );

  // Clear all drop targets
  document.querySelectorAll('.drop-target').forEach(el => el.classList.remove('drop-target'));

  if (cardEl) {
    cardEl.classList.add('drop-target');
  }
}

async function handleDrop(e) {
  e.preventDefault();
  const cardsEl = e.currentTarget;
  const toColumnId = cardsEl.dataset.columnId;

  if (!dragState) return;

  // Find the target card (the one we're dropping before)
  const targetCardEl = [...cardsEl.querySelectorAll('.card:not(.dragging)')].find(
    el => {
      const rect = el.getBoundingClientRect();
      return e.clientY < rect.top + rect.height / 2;
    }
  );

  // Optimistic update: move card in the DOM immediately
  const cardEl = domCache.get(dragState.cardId);
  if (targetCardEl) {
    cardsEl.insertBefore(cardEl, targetCardEl);
  } else {
    cardsEl.appendChild(cardEl);
  }

  // Determine beforeId and afterId for the server request
  let beforeId = null;
  let afterId = null;
  if (targetCardEl) {
    beforeId = targetCardEl.dataset.cardId;
  } else {
    // Find the last card in the column
    const allCards = [...cardsEl.querySelectorAll('.card')].filter(el => el.dataset.cardId !== dragState.cardId);
    if (allCards.length > 0) {
      afterId = allCards[allCards.length - 1].dataset.cardId;
    }
  }

  // Send the move request to the server
  try {
    await moveCard(dragState.cardId, { columnId: toColumnId, beforeId, afterId });
  } catch (err) {
    console.error('Move failed, re-rendering board:', err);
    renderBoard();
  }

  // Clean up
  document.querySelectorAll('.drop-target').forEach(el => el.classList.remove('drop-target'));
  document.querySelectorAll('.column.drag-over').forEach(el => el.classList.remove('drag-over'));
  dragState = null;
}

// ==================== Initialization ====================

async function init() {
  // Fetch initial board state
  const board = await fetchBoard();
  boardState = { columns: {} };
  board.columns.forEach(col => {
    boardState.columns[col.id] = {
      title: col.title,
      position: col.position,
      cards: {},
    };
    col.cards.forEach(card => {
      boardState.columns[col.id].cards[card.id] = card;
    });
  });

  // Render the board
  renderBoard();

  // Connect to SSE for real-time updates
  connectSSE();
}

init();

