const express = require('express');
const cors = require('cors');
const { PGlite } = require('@electric-sql/pglite');
const fs = require('fs');
const path = require('path');

const app = express();
const PORT = 3001;

// Middleware
app.use(cors());
app.use(express.json());

// PGLite instance
let db = null;

// SSE connections
const sseConnections = [];

// ==================== Database Setup ====================

const DB_PATH = path.join(__dirname, '..', 'data', 'kanban.db');

async function initDatabase() {
  // Ensure data directory exists
  const dataDir = path.dirname(DB_PATH);
  if (!fs.existsSync(dataDir)) {
    fs.mkdirSync(dataDir, { recursive: true });
  }

  db = await PGlite.create({
    dataDir: dataDir,
  });

  // Create tables
  await db.exec(`
    CREATE TABLE IF NOT EXISTS columns (
      id TEXT PRIMARY KEY,
      title TEXT NOT NULL,
      position REAL NOT NULL
    );

    CREATE TABLE IF NOT EXISTS cards (
      id TEXT PRIMARY KEY,
      column_id TEXT NOT NULL REFERENCES columns(id),
      text TEXT NOT NULL,
      position REAL NOT NULL,
      created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    );
  `);

  // Seed default columns if empty
  const existing = await db.query('SELECT COUNT(*) AS count FROM columns');
  if (parseInt(existing.rows[0].count) === 0) {
    const colIds = [
      { id: 'col-todo', title: 'To Do', position: 1 },
      { id: 'col-progress', title: 'In Progress', position: 2 },
      { id: 'col-done', title: 'Done', position: 3 },
    ];

    for (const col of colIds) {
      await db.query(
        'INSERT INTO columns (id, title, position) VALUES ($1, $2, $3)',
        [col.id, col.title, col.position]
      );
    }
  }
}

// ==================== SSE Helpers ====================

function broadcast(eventData) {
  const dataStr = JSON.stringify(eventData);
  // Send to all connected SSE clients
  for (const res of sseConnections) {
    try {
      res.write(`data: ${dataStr}\n\n`);
    } catch (err) {
      // Client disconnected
      sseConnections.splice(sseConnections.indexOf(res), 1);
    }
  }
}

function setupSSE(res) {
  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');
  res.setHeader('Access-Control-Allow-Origin', '*');

  // Send initial connection event
  res.write('event: connected\ndata: {"type":"connected"}\n\n');

  sseConnections.push(res);

  res.on('close', () => {
    const idx = sseConnections.indexOf(res);
    if (idx !== -1) {
      sseConnections.splice(idx, 1);
    }
  });
}

// ==================== Position Helpers ====================

function computeNewPosition(db, columnId, beforeId, afterId) {
  let position;

  if (beforeId && afterId) {
    // Insert between two cards
    const beforeResult = await db.query(
      'SELECT position FROM cards WHERE id = $1 AND column_id = $2',
      [beforeId, columnId]
    );
    const afterResult = await db.query(
      'SELECT position FROM cards WHERE id = $1 AND column_id = $2',
      [afterId, columnId]
    );

    const beforePos = beforeResult.rows[0].position;
    const afterPos = afterResult.rows[0].position;

    position = (beforePos + afterPos) / 2;
  } else if (beforeId) {
    // Insert before a card
    const result = await db.query(
      'SELECT position FROM cards WHERE id = $1 AND column_id = $2 ORDER BY position DESC LIMIT 1',
      [beforeId, columnId]
    );
    if (result.rows.length > 0) {
      position = result.rows[0].position - 1;
    } else {
      position = 0.5;
    }
  } else if (afterId) {
    // Insert after a card
    const result = await db.query(
      'SELECT position FROM cards WHERE id = $1 AND column_id = $2 ORDER BY position DESC LIMIT 1',
      [afterId, columnId]
    );
    if (result.rows.length > 0) {
      position = result.rows[0].position + 1;
    } else {
      position = 0.5;
    }
  } else {
    // No reference card, insert at the end
    const result = await db.query(
      'SELECT COALESCE(MAX(position), 0) AS maxPos FROM cards WHERE column_id = $1',
      [columnId]
    );
    position = parseFloat(result.rows[0].maxPos) + 1;
  }

  // Check for precision issues - if position is too close to existing positions
  // we may need to renormalize
  const allCards = await db.query(
    'SELECT id, position FROM cards WHERE column_id = $1 ORDER BY position',
    [columnId]
  );

  for (const card of allCards.rows) {
    if (Math.abs(card.position - position) < 0.001) {
      // Collision detected, renormalize
      await renormalizeColumn(db, columnId);
      return computeNewPosition(db, columnId, beforeId, afterId);
    }
  }

  return position;
}

async function renormalizeColumn(db, columnId) {
  const result = await db.query(
    'SELECT id FROM cards WHERE column_id = $1 ORDER BY position',
    [columnId]
  );

  const cards = result.rows;
  const step = 1.0;
  let pos = 0;

  for (let i = 0; i < cards.length; i++) {
    pos = (i + 1) * step;
    await db.query(
      'UPDATE cards SET position = $1 WHERE id = $2',
      [pos, cards[i].id]
    );
  }

  // Also renormalize columns
  const colResult = await db.query(
    'SELECT id FROM columns ORDER BY position',
    []
  );

  const cols = colResult.rows;
  let colPos = 0;
  for (let i = 0; i < cols.length; i++) {
    colPos = (i + 1) * step;
    await db.query(
      'UPDATE columns SET position = $1 WHERE id = $2',
      [colPos, cols[i].id]
    );
  }
}

// ==================== API Routes ====================

// GET /api/board - Get the full board state
app.get('/api/board', async (req, res) => {
  try {
    const columnsResult = await db.query(
      'SELECT id, title, position FROM columns ORDER BY position'
    );

    const columns = columnsResult.rows.map(col => ({
      id: col.id,
      title: col.title,
      position: col.position,
      cards: [],
    }));

    // Get all cards
    const cardsResult = await db.query(
      'SELECT id, column_id, text, position, created_at FROM cards ORDER BY column_id, position'
    );

    for (const card of cardsResult.rows) {
      const column = columns.find(c => c.id === card.column_id);
      if (column) {
        column.cards.push({
          id: card.id,
          text: card.text,
          position: card.position,
          created_at: card.created_at,
        });
      }
    }

    res.json({ columns });
  } catch (err) {
    console.error('Error fetching board:', err);
    res.status(500).json({ error: 'Failed to fetch board' });
  }
});

// POST /api/cards - Create a new card
app.post('/api/cards', async (req, res) => {
  const { columnId, text } = req.body;

  if (!columnId || !text) {
    return res.status(400).json({ error: 'columnId and text are required' });
  }

  try {
    const cardId = `card-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;

    // Get the current max position in the column
    const maxResult = await db.query(
      'SELECT COALESCE(MAX(position), 0) AS maxPos FROM cards WHERE column_id = $1',
      [columnId]
    );

    const position = parseFloat(maxResult.rows[0].maxPos) + 1;

    await db.query(
      'INSERT INTO cards (id, column_id, text, position) VALUES ($1, $2, $3, $4)',
      [cardId, columnId, text, position]
    );

    // Get column title for broadcast
    const colResult = await db.query(
      'SELECT title FROM columns WHERE id = $1',
      [columnId]
    );

    const card = {
      id: cardId,
      text,
      column_id: columnId,
      position,
      created_at: new Date().toISOString(),
    };

    // Broadcast the new card
    broadcast({
      type: 'card_created',
      card,
      columnId,
    });

    res.json(card);
  } catch (err) {
    console.error('Error creating card:', err);
    res.status(500).json({ error: 'Failed to create card' });
  }
});

// PATCH /api/cards/:id/move - Move a card
app.patch('/api/cards/:id/move', async (req, res) => {
  const { id } = req.params;
  const { columnId, beforeId, afterId } = req.body;

  if (!columnId) {
    return res.status(400).json({ error: 'columnId is required' });
  }

  try {
    // Get the card's current state
    const cardResult = await db.query(
      'SELECT * FROM cards WHERE id = $1',
      [id]
