// ==================== SSE Helpers ====================

function broadcast(eventData) {
  const dataStr = JSON.stringify(eventData);
  for (let i = sseConnections.length - 1; i >= 0; i--) {
    const res = sseConnections[i];
    try {
      res.write(`data: ${dataStr}\n\n`);
    } catch (err) {
      sseConnections.splice(i, 1);
    }
  }
}

function setupSSE(res) {
  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.write('event: connected\ndata: {"type":"connected"}\n\n');
  sseConnections.push(res);
  res.on('close', () => {
    const idx = sseConnections.indexOf(res);
    if (idx !== -1) {
      sseConnections.splice(idx, 1);
    }
  });
}

// ==================== Position Helpers ====================

async function computeNewPosition(tx, columnId, beforeId, afterId) {
  let position;

  if (beforeId && afterId) {
    const beforeResult = await tx.query(
      'SELECT position FROM cards WHERE id = $1 AND column_id = $2',
      [beforeId, columnId]
    );
    const afterResult = await tx.query(
      'SELECT position FROM cards WHERE id = $1 AND column_id = $2',
      [afterId, columnId]
    );

    if (beforeResult.rows.length === 0 || afterResult.rows.length === 0) {
      const maxResult = await tx.query(
        'SELECT COALESCE(MAX(position), 0) AS maxPos FROM cards WHERE column_id = $1',
        [columnId]
      );
      return parseFloat(maxResult.rows[0].maxPos) + 1;
    }

    const beforePos = beforeResult.rows[0].position;
    const afterPos = afterResult.rows[0].position;
    position = (beforePos + afterPos) / 2;
  } else if (beforeId) {
    const result = await tx.query(
      'SELECT position FROM cards WHERE id = $1 AND column_id = $2',
      [beforeId, columnId]
    );
    if (result.rows.length > 0) {
      position = result.rows[0].position - 1;
    } else {
      const maxResult = await tx.query(
        'SELECT COALESCE(MAX(position), 0) AS maxPos FROM cards WHERE column_id = $1',
        [columnId]
      );
      return parseFloat(maxResult.rows[0].maxPos) + 1;
    }
  } else if (afterId) {
    const result = await tx.query(
      'SELECT position FROM cards WHERE id = $1 AND column_id = $2',
      [afterId, columnId]
    );
    if (result.rows.length > 0) {
      position = result.rows[0].position + 1;
    } else {
      const maxResult = await tx.query(
        'SELECT COALESCE(MAX(position), 0) AS maxPos FROM cards WHERE column_id = $1',
        [columnId]
      );
      return parseFloat(maxResult.rows[0].maxPos) + 1;
    }
  } else {
    const maxResult = await tx.query(
      'SELECT COALESCE(MAX(position), 0) AS maxPos FROM cards WHERE column_id = $1',
      [columnId]
    );
    position = parseFloat(maxResult.rows[0].maxPos) + 1;
  }

  return position;
}

async function renormalizeColumn(tx, columnId) {
  const result = await tx.query(
    'SELECT id FROM cards WHERE column_id = $1 ORDER BY position',
    [columnId]
  );

  const cards = result.rows;
  for (let i = 0; i < cards.length; i++) {
    const pos = (i + 1) * 1.0;
    await tx.query(
      'UPDATE cards SET position = $1 WHERE id = $2',
      [pos, cards[i].id]
    );
  }

  return cards.map(c => c.id);
}

async function renormalizeColumns(tx) {
  const colResult = await tx.query(
    'SELECT id FROM columns ORDER BY position',
    []
  );

  const cols = colResult.rows;
  for (let i = 0; i < cols.length; i++) {
    const pos = (i + 1) * 1.0;
    await tx.query(
      'UPDATE columns SET position = $1 WHERE id = $2',
      [pos, cols[i].id]
    );
  }
}

async function getFullBoardState() {
  const columnsResult = await db.query(
    'SELECT id, title, position FROM columns ORDER BY position'
  );

  const columns = columnsResult.rows.map(col => ({
    id: col.id,
    title: col.title,
    position: col.position,
    cards: [],
  }));

  const cardsResult = await db.query(
    'SELECT id, column_id, text, position, created_at FROM cards ORDER BY column_id, position'
  );

  for (const card of cardsResult.rows) {
    const column = columns.find(c => c.id === card.column_id);
    if (column) {
      column.cards.push({
        id: card.id,
        text: card.text,
        position: card.position,
        created_at: card.created_at,
      });
    }
  }

  return { columns };
}

