body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  background: #0079bf;
  min-height: 100vh;
  padding: 20px;
}

#app {
  max-width: 100%;
}

h1 {
  color: white;
  margin-bottom: 20px;
  font-size: 1.5rem;
}

#board {
  display: flex;
  gap: 16px;
  overflow-x: auto;
  align-items: flex-start;
  padding-bottom: 20px;
}

.column {
  background: #ebecf0;
  border-radius: 8px;
  min-width: 280px;
  max-width: 280px;
  padding: 10px;
  flex-shrink: 0;
}

.column-header {
  font-weight: 600;
  padding: 8px 4px;
  font-size: 0.95rem;
  color: #172b4d;
}

.column-cards {
  min-height: 40px;
  padding: 4px 0;
}

.card {
  background: white;
  border-radius: 6px;
  padding: 8px 10px;
  margin-bottom: 8px;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.15);
  cursor: grab;
  font-size: 0.9rem;
  color: #172b4d;
  transition: background 0.15s, box-shadow 0.15s;
  word-wrap: break-word;
}

.card:hover {
  background: #f4f5f7;
}

.card.dragging {
  opacity: 0.5;
  cursor: grabbing;
}

.card.drop-target {
  box-shadow: 0 0 0 2px #0079bf;
}

.add-card-form {
  margin-top: 8px;
  display: flex;
  gap: 4px;
}

.add-card-form input {
  flex: 1;
  padding: 6px 8px;
  border: 2px solid #ddd;
